"""Reference Solution — Lab 02: Custom Retry Analyzer & Flaky Quarantine Engine."""
from typing import Any, Callable, Dict


class RetryAnalyzer:
    TRANSIENT = (TimeoutError, ConnectionError)

    def __init__(self, max_retries: int = 2, base_delay_ms: int = 20) -> None:
        if max_retries < 0 or base_delay_ms < 0:
            raise ValueError("Invalid retry config")
        self.max_retries = max_retries
        self.base_delay_ms = base_delay_ms

    def should_retry(self, exc: BaseException, attempt: int) -> bool:
        return isinstance(exc, self.TRANSIENT) and attempt <= self.max_retries

    def backoff_ms(self, attempt: int) -> int:
        return int(self.base_delay_ms * (2 ** max(0, attempt - 1)))

    def execute(self, fn: Callable[[], Any]) -> Dict[str, Any]:
        attempts = 0
        while True:
            attempts += 1
            try:
                val = fn()
                return {"passed": True, "attempts": attempts, "flaky": attempts > 1, "result": val}
            except BaseException as exc:
                if not self.should_retry(exc, attempts):
                    raise

