"""Reference Solution — Lab 03: Recursive JSON Payload & Schema Diff Engine."""
from typing import Any, Dict, List, Optional, Set


def diff_payloads(
    expected: Any,
    actual: Any,
    ignore_keys: Optional[Set[str]] = None,
    path: str = "$",
) -> List[Dict[str, Any]]:
    ignored = ignore_keys or set()
    diffs: List[Dict[str, Any]] = []
    if type(expected) is not type(actual):
        return [{"path": path, "expected": expected, "actual": actual}]
    if isinstance(expected, dict):
        keys = sorted((set(expected.keys()) | set(actual.keys())) - ignored)
        for k in keys:
            sub = f"{path}.{k}"
            if k not in expected:
                diffs.append({"path": sub, "expected": "<MISSING>", "actual": actual[k]})
            elif k not in actual:
                diffs.append({"path": sub, "expected": expected[k], "actual": "<MISSING>"})
            else:
                diffs.extend(diff_payloads(expected[k], actual[k], ignored, sub))
        return diffs
    if isinstance(expected, list):
        if len(expected) != len(actual):
            return [{"path": f"{path}.length", "expected": len(expected), "actual": len(actual)}]
        for idx, (e_item, a_item) in enumerate(zip(expected, actual)):
            diffs.extend(diff_payloads(e_item, a_item, ignored, f"{path}[{idx}]"))
        return diffs
    if expected != actual:
        diffs.append({"path": path, "expected": expected, "actual": actual})
    return diffs

