"""Reference Solution — Lab 06: Stateful Microservice Stub & Contract Verifier."""
from typing import Any, Dict, List, Tuple


class StatefulServiceStub:
    def __init__(self) -> None:
        self.journal: List[Dict[str, Any]] = []
        self._routes: Dict[Tuple[str, str], List[Tuple[int, Dict[str, Any]]]] = {}

    def stub_sequence(self, method: str, path: str, responses: List[Tuple[int, Dict[str, Any]]]) -> None:
        if not responses:
            raise ValueError("responses cannot be empty")
        self._routes[(method.upper(), path)] = list(responses)

    def handle(self, method: str, path: str, body: Any = None) -> Dict[str, Any]:
        key = (method.upper(), path)
        self.journal.append({"method": key[0], "path": path, "body": body})
        seq = self._routes.get(key)
        if not seq:
            return {"status_code": 404, "data": {"error": "UnstubbedRoute"}}
        status, payload = seq.pop(0) if len(seq) > 1 else seq[0]
        return {"status_code": status, "data": dict(payload)}

    def verify_called(self, method: str, path: str, times: int) -> None:
        actual = sum(1 for r in self.journal if r["method"] == method.upper() and r["path"] == path)
        if actual != times:
            raise AssertionError(f"Expected {times} calls to {method} {path}, recorded {actual}")

